import { fetchText } from '@/lib/seo/files';

// Sitemap index (docs/api/seo.md §5): generated by Laravel's scheduled job, cached here under the
// `sitemaps` tag (the job revalidates it after each build).

// Rendered per request (the API answer is tag-cached in the data cache), never baked at build time.
export const dynamic = 'force-dynamic';

export async function GET(): Promise<Response> {
    const xml = await fetchText('storefront/sitemaps/sitemap.xml', ['sitemaps']);
    if (xml === null) return new Response('Sitemap not available.', { status: 503, headers: { 'Content-Type': 'text/plain; charset=utf-8', 'Retry-After': '3600' } });
    return new Response(xml, { headers: { 'Content-Type': 'application/xml; charset=utf-8', 'Cache-Control': 'public, max-age=3600, s-maxage=3600' } });
}
